use crate::aap::caps::kb_read;

/// Upper bound on the question, in Unicode scalar values (the unit the
/// contract's `len(question)` counts in).
const MAX_QUESTION_CHARS: usize = 512;

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = bound_question(query.query.question);
        let knowledge = kb_read::lookup(&question);

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

/// Enforces the `ensures len(question) <= 512` postcondition. The `requires`
/// clause already bounds the input, so this is normally the identity; it
/// guarantees the output bound regardless.
fn bound_question(question: String) -> String {
    if question.chars().count() <= MAX_QUESTION_CHARS {
        question
    } else {
        question.chars().take(MAX_QUESTION_CHARS).collect()
    }
}

export!(Node);
